import{_ as p,o as t,c as a,a5 as r}from"./chunks/framework.BPFk9-tb.js";const h=JSON.parse('{"title":"百日百字小结","description":"","frontmatter":{"date":"2021-05-07T20:57:20","title":"百日百字小结","categories":["FeelGood"],"tags":["FeelGood"]},"headers":[{"level":2,"title":"链接","slug":"链接","link":"#链接","children":[]}],"relativePath":"posts/achievement/001.md","filePath":"posts/achievement/001.md"}'),n={name:"posts/achievement/001.md"};function o(i,e,s,l,_,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<p>现在已2021年5月7日，把当时购买的《百日百字》的字帖给练完。看了下千聊的购买记录，我是2019年2月的时候买的阿布的《美字修炼课》。如果不是因为小孩子开始写字，不是因为参加了BOX定投践行群，这几本吃灰一年多的字帖可能就要被当垃圾一样扔掉了。</p><p>已经想不起来是因为什么买了这么课，因为什么卖了字帖，可能是自己有一颗想写一手好字的心。但商家可不管你是否真的练好了字，你买了课，你买了字帖，他的营收就有了，其他的事——师父领进门，修行靠个人。</p><p>可想而知的，不是因为工作忙，就是太累了，练字这个事情总是被排到最后，最后不了了之。</p><p>因为孩子上一年级了，作业比较多，其实是写字比较慢，写字来来回回的需要擦掉，于是就给报了个写字课的班，想着能写得更好，更快一些。</p><p>看着小孩用描红本写字，一旁喊，横线要平呀，格子要对齐，线要画到位……反正能找出各种写不好的地方，各种着急，恨不得帮孩子写，就看他写不好，就差动手了。</p><p>要接受刚开始的笨拙，要做榜样，这些话从的脑袋里面迸出来。是呀，学了就要用。于是自己找出来尘封已久的字帖，自己练起来。在孩子做作业的时候，自己就在一旁练字。</p><p>嗯，自己线也描不平呀，该对齐的地方也没对齐，还没结束的时候就结束了，也会超出格子。越是用力，越写不好。自己写了这么多年的字，依然写不好，小孩子刚起步，要求为什么就那么高呢。在一旁说错误是简单的，在一旁发现优点和给予鼓励却不容易。</p><p>这次练字是从1月27日开始的，那段时间，因为自身的原因，没有跟不上且慢的读书写作，感觉到各种焦虑。在决定要开始练字的那一刻，自己是不敢相信自己能完成的——先做在说吧。</p><p>练字期间，最难的反而是节假日，因为节假日，时间安排就会被打乱，不会像工作日那样按部就班的执行就好了。有时快到节假日了，也就只好多练一两篇，或者后面多补一两篇。春节期间能坚持打卡就是多练了几篇，有点存货。</p><p>但有件事情帮到了我，就是我期间参与了笑来老师的写作训练营，发现打卡有利于自己完成目标。于是，自己时不时的在朋友群发练习打卡的照片。</p><p>有时也会觉得现在都用电脑了，写字真的重要么？现在的考试还是笔试，在特定的时间点把该做的事情做好。</p><p>是否对孩子产生了影响，我不知道，我知道有段时间我在他旁边一起练字，他就很开心。</p><p>和练字一起开始记录的是锻炼（深蹲、俯卧撑、引体向上）这两项都几乎能做到每日完成。但自己的写作的输出却很少，写作需要更多的阅读和思考时间，而自己只是懒。</p><h2 id="链接" tabindex="-1">链接 <a class="header-anchor" href="#链接" aria-label="Permalink to &quot;链接&quot;">​</a></h2><p><a href="https://betterexplained.com/articles/surviving-and-thriving-on-your-own-know-thyself/" target="_blank" rel="noreferrer">Surviving (and thriving) on your own: Know Thyself</a></p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',22)])])}const m=p(n,[["render",o]]);export{h as __pageData,m as default};
